                Cache-->>A: Miss
              and Concurrent lookup
                B->>Cache: GET product:42
                Cache-->>B: Miss
              end
              critical Elect loader
                A->>Lock: SET NX product:42
                Lock-->>A: Acquired
              option Loader already elected
                B->>Lock: SET NX product:42
                Lock-->>B: Rejected
              end
