                bigint sku_id PK, FK
                int on_hand
              }
              SUPPLIER {
                bigint id PK
                string name
              }
              PURCHASE_ORDER {
                bigint id PK
                bigint supplier_id FK
                string status
              }
              PURCHASE_LINE {
                bigint order_id PK, FK
                bigint sku_id PK, FK
                int quantity
              }
              TRANSFER {
                bigint id PK
                bigint source_warehouse_id FK
                bigint target_warehouse_id FK
              }
              RESERVATION {
                bigint id PK
                bigint sku_id FK
                bigint warehouse_id FK
                int quantity
              }
              WAREHOUSE ||--|{ BIN : contains
              BIN ||--o{ STOCK : stores
              SKU ||--o{ STOCK : counted_as
              SUPPLIER ||--o{ PURCHASE_ORDER : receives
              PURCHASE_ORDER ||--|{ PURCHASE_LINE : contains
              SKU ||--o{ PURCHASE_LINE : replenishes
              WAREHOUSE ||--o{ TRANSFER : sources
              WAREHOUSE ||--o{ TRANSFER : targets
